import{_ as i,o as u,c as t,a2 as n}from"./chunks/framework.CqpfiAoK.js";const d=JSON.parse('{"title":"Sheria ya Ulinzi wa Watumiaji","description":"","frontmatter":{},"headers":[],"relativePath":"sw/42-消费者保护法.md","filePath":"sw/42-消费者保护法.md","lastUpdated":null}'),h={name:"sw/42-消费者保护法.md"};function k(m,a,r,o,s,l){return u(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="sheria-ya-ulinzi-wa-watumiaji" tabindex="-1">Sheria ya Ulinzi wa Watumiaji <a class="header-anchor" href="#sheria-ya-ulinzi-wa-watumiaji" aria-label="Permalink to &quot;Sheria ya Ulinzi wa Watumiaji&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mradi</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya hati</td><td>42</td></tr><tr><td>Moduli</td><td>Mfumo wa Kisheria na Muundo wa Usimamizi</td></tr><tr><td>Maneno muhimu ya msingi</td><td>Haki za Watumiaji, Biashara ya Haki, Kupinga Udanganyifu, Wajibu wa Bidhaa, Soko la Usawa</td></tr></tbody></table><h2 id="_1-lengo-la-kisheria-na-wigo-wa-utumizi" tabindex="-1">1. Lengo la Kisheria na Wigo wa Utumizi <a class="header-anchor" href="#_1-lengo-la-kisheria-na-wigo-wa-utumizi" aria-label="Permalink to &quot;1. Lengo la Kisheria na Wigo wa Utumizi&quot;">​</a></h2><p>《Sheria ya Ulinzi wa Watumiaji》 ni moja ya sheria za msingi katika mfumo wa kisheria wa ustaarabu wa usawa wa nanga, na pamoja na 《Sheria ya Kazi ya Usawa》 huunda misingi miwili ya maisha ya kiuchumi. Sheria hii inalenga kulinda haki na maslahi halali ya watumiaji wote ndani ya Hengyuanzhou, kurekebisha tabia za biashara za soko, kudumisha utaratibu wa soko wa haki, uaminifu, na usawa, na kuzuia ukiukaji wa haki na maslahi ya kila kiumbe na tabia za kibiashara za mauaji.</p><p>Sheria hii inatumika kwa watumiaji wote ndani ya Hengyuanzhou ambao wanunua, wanatumia bidhaa, au wanapokea huduma ili kukidhi mahitaji ya maisha ya kibinafsi au ya familia, na pia kwa wafanyabiashara ambao wanatoa bidhaa au huduma kwa watumiaji. Biashara za kati ya viwango pia zinatumika kwa sheria hii, lakini kanuni za maelezo ya utekelezaji zinaweza kutungwa kulingana na tofauti za viwango.</p><h2 id="_2-haki-za-msingi-za-watumiaji" tabindex="-1">2. Haki za Msingi za Watumiaji <a class="header-anchor" href="#_2-haki-za-msingi-za-watumiaji" aria-label="Permalink to &quot;2. Haki za Msingi za Watumiaji&quot;">​</a></h2><p>Sheria hii inaweka kwamba watumiaji wanafurahia haki zifuatazo tisa za msingi:</p><table tabindex="0"><thead><tr><th>Haki</th><th>Maudhui</th></tr></thead><tbody><tr><td>Haki ya Uhakikisho wa Usalama</td><td>Mtumiaji wakati anunua, anatumia bidhaa, na anapokea huduma anafurahia haki ya usalama wa mtu na mali usihataribiwe</td></tr><tr><td>Haki ya Kujua Kweli</td><td>Mtumiaji ana haki ya kujua hali halisi ya bidhaa anayonua au kutumia au huduma anayopokea, ikiwa ni pamoja na viungo, ufanisi, hatari, n.k.</td></tr><tr><td>Haki ya Uchaguzi wa Kujitegemea</td><td>Mtumiaji ana haki ya kuchagua bidhaa au huduma kwa uhuru, ana haki ya kufanya kulinganisha, kutambua, na kuchagua, na kukataa biashara ya kulazimisha</td></tr><tr><td>Haki ya Biashara ya Haki</td><td>Mtumiaji ana haki ya kupata masharti ya biashara ya haki kama vile uhakikisho wa ubora, bei ya kufaa, upimaji sahihi, n.k.</td></tr><tr><td>Haki ya Ufidhi kulingana na Sheria</td><td>Mtumiaji akitabiriwa uharibifu wa mtu au mali kutokana na kununua, kutumia bidhaa, au kupokea huduma anafurahia haki ya kupata fidha kulingana na sheria</td></tr><tr><td>Haki ya Kuunda Shirika la Kulinda Haki</td><td>Mtumiaji ana haki ya kuunda au kujiunga na shirika la watumiaji kulingana na sheria, na kulinda haki na maslahi yake halali</td></tr><tr><td>Haki ya Kupata Maarifa</td><td>Mtumiaji ana haki ya kupata maarifa na taarifa zinazohusiana na matumizi na ulinzi wa haki na maslahi ya mtumiaji</td></tr><tr><td>Haki ya Kuheshimiwa</td><td>Mtumiaji wakati anunua, anatumia bidhaa, na anapokea huduma anafurahia haki ya heshima ya mtu na desturi za kieta zikiheshimiwa</td></tr><tr><td>Haki ya Ushirikiano</td><td>Mtumiaji ana haki ya kufanya ushirikiano juu ya bidhaa na huduma na kazi ya ulinzi wa haki na maslahi ya mtumiaji, na kutoa ukosoaji na mapendekezo</td></tr></tbody></table><h2 id="_3-wajibu-wa-mfanyabiashara" tabindex="-1">3. Wajibu wa Mfanyabiashara <a class="header-anchor" href="#_3-wajibu-wa-mfanyabiashara" aria-label="Permalink to &quot;3. Wajibu wa Mfanyabiashara&quot;">​</a></h2><p>Mfanyabiashara wakati anatoa bidhaa au huduma kwa watumiaji anapaswa kutimiza wajibu ufuatao:</p><ol><li><strong>Wajibu wa Kufanya Biashara kulingana na Sheria</strong>: Mfanyabiashara lazima atii Katiba na sheria, na afanye shughuli za kibiashara ndani ya upeo wa biashara ulioidhinishwa.</li><li><strong>Wajibu wa Uhakikisho wa Usalama</strong>: Mfanyabiashara lazima ahakikishe kwamba bidhaa au huduma anazotoa zinakidhi mahitaji ya uhakikisho wa usalama wa mtu na mali, na lazima atoelezea kwa kweli na kutoa onyo dhahiri kwa bidhaa na huduma ambazo zinaweza kuhatarisha usalama.</li><li><strong>Wajibu wa Taarifa za Kweli</strong>: Mfanyabiashara lazima atoe watumiaji taarifa za kweli kuhusu bidhaa au huduma, na asiweke tangazo la uongo au la udanganyifu. Bidhaa na huduma za aina ya mazoezi lazima ziandike kwa kweli mipaka ya ufanisi na hatari zinazowezekana.</li><li><strong>Wajibu wa Uhakikisho wa Ubora</strong>: Mfanyabiashara lazima ahakikishe kwamba katika hali za matumizi ya kawaida ya bidhaa au upokeaji wa huduma, bidhaa au huduma anazotoa zina ubora, utendaji, matumizi, na muda wa uhalifu ambao wanapaswa kuwa nao.</li><li><strong>Wajibu wa Biashara ya Haki</strong>: Mfanyabiashara hanaweza kupitia masharti ya kawaida, taarifa, tangazo, tangazo la duka, n.k. kufanya masharti yasiyo ya haki na yasiyo ya kufaa kwa watumiaji, kama vile kuondoa au kupunguza haki za mtumiaji, kupunguza au kuwaacha huru wajibu wa mfanyabiashara, kuongeza uzito wajibu wa mtumiaji, n.k.</li><li><strong>Wajibu wa Huduma baada ya Mauzo</strong>: Mfanyabiashara lazima, kulingana na masharti ya serikali au makubaliano na mtumiaji, abebe wajibu wa ukarabati, uingizwaji, urejesho, na wajibu mwingine wa huduma baada ya mauzo.</li><li><strong>Wajibu wa Ulinzi wa Faragha</strong>: Mfanyabiashara lazima alinde taarifa za kibinafsi na data za fahamu za mtumiaji, na asiweze kukusanya, kutumia, au kufichua bila idhini ya mtumiaji.</li></ol><h2 id="_4-kutatua-mizozo-na-wajibu-wa-kisheria" tabindex="-1">4. Kutatua Mizozo na Wajibu wa Kisheria <a class="header-anchor" href="#_4-kutatua-mizozo-na-wajibu-wa-kisheria" aria-label="Permalink to &quot;4. Kutatua Mizozo na Wajibu wa Kisheria&quot;">​</a></h2><p>Wakati mitatizo ya haki na maslahi ya mtumiaji inatokea kati ya mtumiaji na mfanyabiashara, inaweza kutatuliwa kupitia njia zifuatazo:</p><ul><li>Mazungumzo na makubaliano na mfanyabiashara</li><li>Kuomba usulishaji kutoka shirika la watumiaji</li><li>Kuomba malalamiko kwa idara inayohusiana ya utawala</li><li>Kuomba arbitri kutoka chuo cha arbitri kulingana na makubaliano ya arbitri yaliyofanywa na mfanyabiashara</li><li>Kuwasilisha kesi Korti ya Usawa</li></ul><p>Mfanyabiashara anayevunja masharti ya sheria hii na kuukiza haki na maslahi halali ya mtumiaji atabeba wajibu ufuatao:</p><table tabindex="0"><thead><tr><th>Tabia ya Kikatili</th><th>Wajibu wa Kisheria</th></tr></thead><tbody><tr><td>Kutoa bidhaa au huduma zilizo na kasoro na kusababisha uharibifu</td><td>Kubeba wajibu wa fidha, ikiwa ni pamoja na gharama za matibabu, fidha ya kupoteza kazi, fidha ya ulemavu, n.k.</td></tr><tr><td>Tabia ya udanganyifu</td><td>Kuongeza fidha kulingana na ombi la mtumiaji, kiwango cha mara tatu cha bei ya bidhaa mtumiaji aliyonunua au gharama ya huduma aliyopokea</td></tr><tr><td>Tangazo la uongo</td><td>Kuamriwa kusitisha tabia ya kikatili, kuondoa athari, kulipwa faini</td></tr><tr><td>Biashara ya kulazimisha</td><td>Kuamriwa kurekebisha, kurejesha gharama zisizo za kufaa, kulipwa faini</td></tr><tr><td>Kuukiza faragha ya mtumiaji</td><td>Kubeba fidha ya uharibifu wa kiakili, katika visa vizito kufuatiliwa kwa wajibu wa jinai</td></tr></tbody></table><h2 id="_5-mashirika-ya-watumiaji-na-ushirikiano-wa-jamii" tabindex="-1">5. Mashirika ya Watumiaji na Ushirikiano wa Jamii <a class="header-anchor" href="#_5-mashirika-ya-watumiaji-na-ushirikiano-wa-jamii" aria-label="Permalink to &quot;5. Mashirika ya Watumiaji na Ushirikiano wa Jamii&quot;">​</a></h2><p>Serikali inachochea na kusaidia mashirika na watu wote kufanya ushirikiano wa jamii juu ya tabia zinazozaribu haki na maslahi halali ya mtumiaji. Chama cha Watumiaji ni shirika la jamii lililoanzishwa kulingana na sheria kufanya ushirikiano wa jamii juu ya bidhaa na huduma na kulinda haki na maslahi halali ya mtumiaji, na hufanya kazi zifuatazo:</p><ol><li>Kutoa watumiaji taarifa za matumizi na huduma ya ushauri</li><li>Kushiriki katika ushirikiano na ukaguzi wa bidhaa na huduma kwa idara inayohusiana ya utawala</li><li>Kuripoti, kuchunguza, na kutoa mapendekezo kwa idara inayohusiana ya utawala kuhusu masuala yanayohusu haki na maslahi halali ya mtumiaji</li><li>Kupokea malalamiko ya watumiaji, na kufanya uchunguzi na usulishaji wa masuala yaliyolalamikiwa</li><li>Kuunga mkono watumiaji waliohataribiwa kuwasilisha kesi dhidi ya tabia zinazozaribu haki na maslahi halali ya mtumiaji</li></ol><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>《Sheria ya Ulinzi wa Watumiaji》 ni mlinzi wa utaratibu wa soko wa ustaarabu wa usawa wa nanga. Kupitia kutoa watumiaji haki za kutosha, kuzuia tabia za wafanyabiashara, na kujenga mfumo wa kutatua mizozo anuwai, inahakikisha kwamba biashara za soko zinaendelea kwenye njia ya haki, uaminifu, na usawa, na kuzuia sekta ya kibiashara kuwa mazingira mapya ya tabia za mauaji.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Kanuni za Msingi za Katiba ya Usawa)</li><li>41-共生劳动法 (Sheria ya Kazi ya Usawa)</li><li>47-反垄断法 (Sheria ya Kupinga Umoja wa Monopoli)</li><li>36-社会结构与阶层流动 (Muundo wa Jamii na Uhamiaji wa Tabaka)</li></ul>',23)])])}const w=i(h,[["render",k]]);export{d as __pageData,w as default};
